"""Guard rails that keep synthetic demo data from ever being presented as research."""

from __future__ import annotations

import psycopg

DEMO_SOURCES = ("synthetic",)
DEMO_MESSAGE_TAG = "[demo]"

BANNER = (
    "> **SYNTHETIC DEMO DATA — NOT RESEARCH RESULTS.** Every price and message in this run "
    "was generated by `worker/demo`. Use it to validate the pipeline, never to draw market "
    "conclusions. Real results require the real ingestion paths (`ingest telegram`, "
    "`prices nobitex|xauusd|tgju|tsetmc`)."
)


def counts(conn: psycopg.Connection) -> dict[str, int]:
    out: dict[str, int] = {}
    for name, sql in (
        ("price_bars_synthetic", "select count(*) as n from price_bars where source = 'synthetic'"),
        ("messages_demo", f"select count(*) as n from messages where raw_text like '{DEMO_MESSAGE_TAG}%'"),
        ("messages_total", "select count(*) as n from messages"),
        ("price_bars_real", "select count(*) as n from price_bars where source <> 'synthetic'"),
    ):
        row = conn.execute(sql).fetchone()
        out[name] = int(row["n"]) if row else 0
    return out


def is_demo_run(conn: psycopg.Connection) -> bool:
    """True when the database holds synthetic bars and no real ones."""
    c = counts(conn)
    return c["price_bars_synthetic"] > 0 and c["price_bars_real"] == 0


def banner_for(conn: psycopg.Connection) -> str:
    return BANNER if is_demo_run(conn) else ""
